select
a.user_id,
a.user_name,
a.PASSWORD,
a.true_name,
a.user_type,
a.sex,
a.e_mail,
a.mobile_phone,
a.work_no,
a.face_id,
a.finger_id,
a.voice_id,
a.state,
a.user_title,
a.creator_id,
a.appkey,
a.image_url,
a.role_id,
a.org_id,
a.user_status,
a.create_time,
a.update_time,
a.invalid_time,
a.last_login
from sys_user a
where 1 = 1
 and a.user_id = #{userId, jdbcType=BIGINT}
 and a.user_name = #{userName, jdbcType=VARCHAR}
 and a.PASSWORD = #{password, jdbcType=VARCHAR}
 and a.true_name = #{trueName, jdbcType=VARCHAR}
 and a.user_type = #{userType, jdbcType=INTEGER}
 and a.sex = #{sex, jdbcType=INTEGER}
 and a.e_mail = #{eMail, jdbcType=VARCHAR}
 and a.mobile_phone = #{mobilePhone, jdbcType=VARCHAR}
 and a.work_no = #{workNo, jdbcType=VARCHAR}
 and a.face_id = #{faceId, jdbcType=VARCHAR}
 and a.finger_id = #{fingerId, jdbcType=VARCHAR}
 and a.voice_id = #{voiceId, jdbcType=VARCHAR}
 and a.state = #{state, jdbcType=INTEGER}
 and a.user_title = #{userTitle, jdbcType=VARCHAR}
 and a.creator_id = #{creatorId, jdbcType=BIGINT}
 and a.appkey = #{appkey, jdbcType=VARCHAR}
 and a.image_url = #{imageUrl, jdbcType=VARCHAR}
 and a.role_id = #{roleId, jdbcType=BIGINT}
 and a.org_id = #{orgId, jdbcType=BIGINT}
 and a.user_status = #{userStatus, jdbcType=INTEGER}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.invalid_time = #{invalidTime, jdbcType=TIMESTAMP}
 and a.last_login = #{lastLogin, jdbcType=TIMESTAMP}

select
a.user_id,
a.user_name,
a.PASSWORD,
a.true_name,
a.user_type,
a.sex,
a.e_mail,
a.mobile_phone,
a.work_no,
a.face_id,
a.finger_id,
a.voice_id,
a.state,
a.user_title,
a.creator_id,
a.appkey,
a.image_url,
a.role_id,
c.role_name,
a.org_id,
b.org_name,
a.user_status,
DATE_FORMAT(a.create_time ,'%Y-%m-%d %H:%i:%s') AS create_time,
DATE_FORMAT(a.update_time ,'%Y-%m-%d %H:%i:%s') AS update_time,
DATE_FORMAT(a.invalid_time ,'%Y-%m-%d %H:%i:%s') AS invalid_time,
DATE_FORMAT(a.last_login ,'%Y-%m-%d %H:%i:%s') AS last_login
from sys_user a
LEFT JOIN sys_org b ON a.org_id = b.org_id
LEFT JOIN sys_role c ON a.role_id = c.role_id
where 1 = 1 AND a.state != 0
 and a.user_id = #{userId, jdbcType=BIGINT}
 and a.user_name like concat('%',#{userName, jdbcType=VARCHAR},'%') 
 and a.PASSWORD = #{password, jdbcType=VARCHAR}
 and a.true_name = #{trueName, jdbcType=VARCHAR}
 and a.user_type = #{userType, jdbcType=INTEGER}
 and a.sex = #{sex, jdbcType=INTEGER}
 and a.e_mail = #{eMail, jdbcType=VARCHAR}
 and a.mobile_phone = #{mobilePhone, jdbcType=VARCHAR}
 and a.work_no = #{workNo, jdbcType=VARCHAR}
 and a.face_id = #{faceId, jdbcType=VARCHAR}
 and a.finger_id = #{fingerId, jdbcType=VARCHAR}
 and a.voice_id = #{voiceId, jdbcType=VARCHAR}
 and a.state = #{state, jdbcType=INTEGER}
 and a.user_title = #{userTitle, jdbcType=VARCHAR}
 and a.creator_id = #{creatorId, jdbcType=BIGINT}
 and a.appkey = #{appkey, jdbcType=VARCHAR}
 and a.image_url = #{imageUrl, jdbcType=VARCHAR}
 and a.role_id = #{roleId, jdbcType=BIGINT}
 and a.org_id = #{orgId, jdbcType=BIGINT}
 and a.user_status = #{userStatus, jdbcType=INTEGER}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.invalid_time = #{invalidTime, jdbcType=TIMESTAMP}
 and a.last_login = #{lastLogin, jdbcType=TIMESTAMP}

select * from sys_user a
where 1=1
and a.state = #{state, jdbcType=INTEGER}

select * from sys_user a
WHERE 1=1
and a.user_name = #{userName, jdbcType=VARCHAR}
